/** A project lead must be a current, active member of the org. */
async function assertValidLead(
  orgId: OrgId,
  leadId: UserId | null,
): Promise<void> {
  if (leadId === null) return;

  const member = await memberRepo.findMember(orgId, leadId);
  if (!member || member.status !== "active") {
    throw new NotFoundError("Member", leadId);
  }
}

